import{_ as s,l as d,o as a,c as l,v as o,p as c,x as t,d as r,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"静态对动态链接","description":"","frontmatter":{"title":"静态对动态链接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/static-vs-dynamic-link.md","filePath":"cs/static-vs-dynamic-link.md","lastUpdated":1789023840000}'),h={name:"cs/static-vs-dynamic-link.md"};function _(E,e,m,T,A,u){const i=d("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="静态对动态链接" tabindex="-1">静态对动态链接 <a class="header-anchor" href="#静态对动态链接" aria-label="Permalink to &quot;静态对动态链接&quot;">​</a></h1><div class="epigraph"><p>静态把库目标编进可执行文件；动态把依赖推迟到加载，符号经 GOT/PLT 绑定。二者对体积、更新与启动时间的答案相反。</p><footer>—— 据 Levine；主干[GOT 与 PLT](/cs/got-plt)、[加载与动态链接](/cs/load-dynlink)；System V ABI 整理</footer></div><p>上一课<a href="/cs/linker-script-sections">链接脚本</a> 排段。缺口是<strong>库怎么交付</strong>：<code>.a</code> 抽进文本 vs <code>.so</code> 运行时映射。主干已有 GOT/PLT。本课钉权衡与符号绑定时机（立即/延迟），插入下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态：闭世界，LTO 狠，无启动解析，体积大、安全更新要重链。动态：共享内存页、可替换 <code>.so</code>，启动走加载器，ABI 必须稳。缺口是<strong>选择合同</strong>，不是脚本语法。</p><p>PIE：可执行也位置无关，ASLR。静态 PIE 存在，但是另一打包。</p><h3 id="动态不是「不链接」" tabindex="-1">动态不是「不链接」 <a class="header-anchor" href="#动态不是「不链接」" aria-label="Permalink to &quot;动态不是「不链接」&quot;">​</a></h3><p>仍有链接：产生 <code>DT_NEEDED</code> 与重定位。只是把最终地址推迟。不要说动态程序「没被链接」。</p><p><span class="marginnote">Levine。SysV。主干 got-plt、load-dynlink。本课对照表，不重画 PLT 桩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>gcc -static</code> vs 默认动态。查看：<code>ldd</code>、<code>readelf -d</code>。静态 libc 的法律与兼容（glibc 不鼓励完全静态）是工程现实。musl 更常静态。</p>',11)),(a(),c(p,null,{default:t(()=>[n(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22.o%22%5D%20--%3E%20ST%5B%22%E9%9D%99%E6%80%81%EF%BC%9A%E6%94%B6%E8%BF%9B%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%0A%20%20SRC%20--%3E%20DY%5B%22%E5%8A%A8%E6%80%81%EF%BC%9ADT_NEEDED%22%5D%0A%20%20DY%20--%3E%20LDSO%5B%22%E5%8A%A0%E8%BD%BD%E5%99%A8%E7%BB%91%E5%AE%9A%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与可见性：动态导出过多则慢且易冲突。<code>--exclude-libs</code> 等。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>版本：<code>GLIBC_2.xx</code> 符号版本。静态无此运行时绑定，但内核 syscall 仍在。不要把静态当「无未定义行为」。</p><p>插件：<code>dlopen</code> 只在动态世界自然；静态要自注册表。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 <code>LD_PRELOAD</code> 全文。后课默认：动态靠 GOT/PLT 与加载器。下一课符号插入与 <code>LD_PRELOAD</code>。</p><p>也不把动态链接当解释器字节码。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>静态：闭世界、体积、更新难。</li><li>动态：共享与可替换，推迟绑定。</li><li>仍有链接，只是分阶段。</li><li>出处：Levine；System V ABI；对照主干 GOT/PLT。</li></ul>',9))])}const f=s(h,[["render",_]]);export{P as __pageData,f as default};
